import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"Feature: Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"features/authentication.md","filePath":"features/authentication.md","lastUpdated":1786090478000}'),r={name:"features/authentication.md"};function c(n,t,i,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="feature-authentication" tabindex="-1">Feature: Authentication <a class="header-anchor" href="#feature-authentication" aria-label="Permalink to &quot;Feature: Authentication&quot;">​</a></h1><p>Каталог: <code>src/features/authentication/</code>.</p><p>Авторизация по телефону (SMS), upgrade анонимной сессии, имя пользователя, logout / удаление аккаунта.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authentication/</span></span>
<span class="line"><span>├── store/authStore.ts</span></span>
<span class="line"><span>├── services/authService.ts</span></span>
<span class="line"><span>├── types/index.ts</span></span>
<span class="line"><span>├── composables/useAuthPhone.ts</span></span>
<span class="line"><span>├── views/AuthenticationView/</span></span>
<span class="line"><span>└── components/</span></span>
<span class="line"><span>    ├── AuthenticationForm/</span></span>
<span class="line"><span>    ├── AuthenticationFormPhone/, AuthenticationFormCode/, AuthenticationFormName/</span></span>
<span class="line"><span>    ├── AuthenticationTitle/, AuthenticationLogo/, AuthenticationErrors/</span></span></code></pre></div><p>Монтируется из <code>App.vue</code> как <code>&lt;AuthenticationView /&gt;</code>. Видимость: <code>v-if=&quot;getIsOpenPopup&quot;</code>.</p><hr><h2 id="типы-types-index-ts" tabindex="-1">Типы (<code>types/index.ts</code>) <a class="header-anchor" href="#типы-types-index-ts" aria-label="Permalink to &quot;Типы (\`types/index.ts\`)&quot;">​</a></h2><p>Единственный интерфейс — <code>IAuthState</code>:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Тип</th><th>Смысл</th></tr></thead><tbody><tr><td><code>userName</code></td><td><code>string | null</code></td><td>Имя; <code>getIsLoggedIn = Boolean(userName)</code></td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td>В state есть; <strong>actions не меняют</strong></td></tr><tr><td><code>error</code></td><td><code>string | null</code></td><td>Код/текст ошибки API</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td>1 телефон → 2 код → 3 имя</td></tr><tr><td><code>phone</code></td><td><code>string</code></td><td>Нормализованный (<code>+7955…</code>)</td></tr><tr><td><code>formattedPhone</code></td><td><code>string</code></td><td>Маска <code>+7 (955) 555-55-55</code></td></tr><tr><td><code>isOpenPopup</code> / <code>isOpenFromChat</code></td><td><code>boolean</code></td><td>Popup и контекст из чата</td></tr><tr><td><code>userType</code></td><td><code>string | null</code></td><td><code>ANONYMOUS</code> / <code>REGISTERED</code> и т.п.</td></tr><tr><td><code>accessTokenExpiresAt</code> / <code>refreshTokenExpiresAt</code></td><td><code>string | null</code></td><td>Expiry токенов</td></tr><tr><td><code>durationDisable</code></td><td><code>number</code></td><td>Секунды до повторной SMS (дефолт 60)</td></tr></tbody></table><p>Ответы API в types не описаны.</p><hr><h2 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;Cookies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ключ</th><th>Содержимое</th></tr></thead><tbody><tr><td><code>gpAccessTokenExpiresAt</code></td><td>ISO-время истечения access</td></tr><tr><td><code>gpRefreshTokenExpiresAt</code></td><td>ISO-время истечения refresh</td></tr></tbody></table><p>В cookie — <strong>даты expiry</strong>, не JWT. Сами токены — на стороне HTTP (Set-Cookie бэкенда).</p><p>Пишутся в <code>upgradeSession</code> / <code>updateToken</code>; удаляются в <code>logout</code> / <code>deleteAccount</code>. Init стора читает cookies при старте.</p><hr><h2 id="authservice-services-authservice-ts" tabindex="-1">authService (<code>services/authService.ts</code>) <a class="header-anchor" href="#authservice-services-authservice-ts" aria-label="Permalink to &quot;authService (\`services/authService.ts\`)&quot;">​</a></h2><p>Real/mock: <code>getIsRealDataSber()</code> (<code>?fake</code> → mock JSON из <code>/tests/auth/</code>).</p><table tabindex="0"><thead><tr><th>Метод</th><th>HTTP</th><th>Path</th><th>Body</th></tr></thead><tbody><tr><td><code>authMe</code></td><td>GET</td><td><code>/api/auth/me</code></td><td>—</td></tr><tr><td><code>refreshToken</code></td><td>POST</td><td><code>/api/auth/refresh</code></td><td>—</td></tr><tr><td><code>anonymousLogin</code></td><td>POST</td><td><code>/api/auth/anonymous/init</code></td><td>—</td></tr><tr><td><code>sendCode</code></td><td>POST</td><td><code>/api/auth/phone/send-code</code></td><td><code>{ phone }</code></td></tr><tr><td><code>verifyCode</code></td><td>POST</td><td><code>/api/auth/phone/verify</code></td><td><code>{ phone, code }</code></td></tr><tr><td><code>upgradeSession</code></td><td>POST</td><td><code>/api/auth/phone/upgrade</code></td><td><code>{ phone }</code></td></tr><tr><td><code>changeUserName</code></td><td>PATCH</td><td><code>/api/auth/me</code></td><td><code>{ name }</code></td></tr><tr><td><code>logout</code></td><td>POST</td><td><code>/api/auth/logout</code></td><td>—</td></tr><tr><td><code>deleteAccount</code></td><td>POST</td><td><code>/api/auth/me/delete-account</code></td><td>—</td></tr></tbody></table><p>Mock почти везде <code>GET</code> без body. Store ожидает у send-code поле <strong><code>retryAfterSeconds</code></strong> (в mock может быть <code>duration</code> — расхождение).</p><hr><h2 id="authstore-store-authstore-ts" tabindex="-1">authStore (<code>store/authStore.ts</code>) <a class="header-anchor" href="#authstore-store-authstore-ts" aria-label="Permalink to &quot;authStore (\`store/authStore.ts\`)&quot;">​</a></h2><p>Pinia id: <code>&#39;auth&#39;</code>.</p><h3 id="getters" tabindex="-1">Getters <a class="header-anchor" href="#getters" aria-label="Permalink to &quot;Getters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Getter</th><th>Возвращает</th></tr></thead><tbody><tr><td><code>getUserName</code> / <code>getIsLoggedIn</code></td><td>имя; <code>Boolean(userName)</code></td></tr><tr><td><code>getStep</code> / <code>getPhone</code> / <code>getFormattedPhone</code></td><td>шаг и телефон</td></tr><tr><td><code>getIsOpenPopup</code> / <code>getIsOpenFromChat</code></td><td>popup</td></tr><tr><td><code>getError</code> / <code>getDurationDisable</code></td><td>ошибка / таймер SMS</td></tr><tr><td><code>getUserType</code></td><td>тип сессии</td></tr><tr><td><code>getAccessToken</code> / <code>getRefreshToken</code></td><td><strong>expiry</strong> (имена геттеров вводят в заблуждение)</td></tr></tbody></table><h3 id="actions-—-ui-локальное" tabindex="-1">Actions — UI / локальное <a class="header-anchor" href="#actions-—-ui-локальное" aria-label="Permalink to &quot;Actions — UI / локальное&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Поведение</th></tr></thead><tbody><tr><td><code>openPopupAuth(fromChat?)</code></td><td><code>isOpenPopup = true</code>, <code>isOpenFromChat</code></td></tr><tr><td><code>closePopupAuth()</code></td><td><code>isOpenPopup = false</code> (<code>isOpenFromChat</code> <strong>не</strong> сбрасывается)</td></tr><tr><td><code>setStep</code> / <code>incrementStep</code> / <code>decrementStep</code></td><td>Шаги формы</td></tr><tr><td><code>setFormattedPhone</code> / <code>setPhone</code></td><td>Нормализация / маска</td></tr><tr><td><code>resetAuthData()</code></td><td><code>step = 1</code>, телефоны <code>&#39;&#39;</code> (имя/токены не трогает)</td></tr><tr><td><code>setErrorInfo(error)</code></td><td>Ручная ошибка</td></tr></tbody></table><h3 id="actions-—-сеть-сессия" tabindex="-1">Actions — сеть / сессия <a class="header-anchor" href="#actions-—-сеть-сессия" aria-label="Permalink to &quot;Actions — сеть / сессия&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Поведение</th></tr></thead><tbody><tr><td><code>sendCode()</code></td><td>SMS; при успехе → <code>durationDisable</code> из <code>retryAfterSeconds</code>; ошибка → <code>error</code> + throw</td></tr><tr><td><code>verifyCode(code)</code></td><td>Проверка OTP; state токенов не меняет</td></tr><tr><td><code>upgradeSession()</code></td><td>Связка анонимной сессии с телефоном → <code>userName</code>, phone, <strong>cookies expiry</strong></td></tr><tr><td><code>changeUserName(name)</code></td><td>PATCH имени → <code>userName</code></td></tr><tr><td><code>authMe()</code></td><td>Текущая сессия → <code>userType</code>, name, phone</td></tr><tr><td><code>updateToken()</code></td><td>Refresh → cookies; зовёт interceptor чатов при 401</td></tr><tr><td><code>anonymousLogin()</code></td><td>Анонимная сессия после logout</td></tr></tbody></table><h3 id="actions-—-logout-deleteaccount" tabindex="-1">Actions — logout / deleteAccount <a class="header-anchor" href="#actions-—-logout-deleteaccount" aria-label="Permalink to &quot;Actions — logout / deleteAccount&quot;">​</a></h3><ol><li>Локально: <code>userName = null</code>, <code>step = 1</code>, телефоны <code>&#39;&#39;</code>.</li><li><code>deleteCookie</code> обеих expiry.</li><li>API <code>logout</code> / <code>deleteAccount</code>.</li><li><code>anonymousLogin()</code>.</li><li><code>chatStore.clearAllChats()</code>.</li><li><code>eventBus.emit(&#39;chat:clear-visual&#39;)</code>.</li></ol><p><code>settingsStore</code> из authStore <strong>не</strong> вызывается.</p><hr><h2 id="useauthphone" tabindex="-1">useAuthPhone <a class="header-anchor" href="#useauthphone" aria-label="Permalink to &quot;useAuthPhone&quot;">​</a></h2><p><strong>Путь:</strong> <code>composables/useAuthPhone.ts</code></p><p>Общая логика телефона + agreement для <code>AuthenticationFormPhone</code> и <code>SidebarLogin</code>.</p><table tabindex="0"><thead><tr><th>Константа</th><th>Значение</th></tr></thead><tbody><tr><td><code>phoneMaskLength</code></td><td>18</td></tr></tbody></table><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Export</th><th>Смысл</th></tr></thead><tbody><tr><td><code>phone</code> / <code>checkedAgreement</code> / <code>errorAgreement</code></td><td>Локальный state</td></tr><tr><td><code>disabledButton</code></td><td>нет согласия <strong>или</strong> длина ≠ 18</td></tr><tr><td><code>authError</code></td><td>RU-текст из store error</td></tr><tr><td><code>phoneTextHandler</code> / <code>agreementChangeHandler</code></td><td>Инпут / toggle</td></tr><tr><td><code>buttonClickHandler</code></td><td>Валидация → <code>setFormattedPhone</code> → <code>sendCode</code> → при успехе: <code>openPopupAuth()</code> если закрыт + <code>incrementStep()</code></td></tr></tbody></table><h3 id="маппинг-autherror" tabindex="-1">Маппинг <code>authError</code> <a class="header-anchor" href="#маппинг-autherror" aria-label="Permalink to &quot;Маппинг \`authError\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Код API</th><th>Текст</th></tr></thead><tbody><tr><td><code>sms_rate_limited</code></td><td>«Превышен лимит запросов кода подтверждения»</td></tr><tr><td><code>session_sms_limit</code></td><td>«Превышен лимит номеров телефона»</td></tr><tr><td><code>null</code></td><td><code>&#39;&#39;</code></td></tr><tr><td>иное</td><td>«Ошибка авторизации»</td></tr></tbody></table><hr><h2 id="поток-1-→-2-→-3" tabindex="-1">Поток 1 → 2 → 3 <a class="header-anchor" href="#поток-1-→-2-→-3" aria-label="Permalink to &quot;Поток 1 → 2 → 3&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  open[openPopupAuth] --&gt; step1[Step 1 Phone]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step1 --&gt;|sendCode OK| step2[Step 2 Code]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step2 --&gt;|verifyCode + upgradeSession + fetchUserChats| check{userName?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check --&gt;|да| close[closePopupAuth]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check --&gt;|нет| step3[Step 3 Name]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step3 --&gt;|changeUserName OK| close</span></span></code></pre></div><table tabindex="0"><thead><tr><th>После успешного OTP + upgrade</th><th>Действие</th></tr></thead><tbody><tr><td><code>userName</code> уже есть</td><td><code>closePopupAuth()</code> — шаг 3 не показывают</td></tr><tr><td><code>userName</code> пустой</td><td><code>incrementStep()</code> → имя → после <code>changeUserName</code> → close</td></tr></tbody></table><p>Back: <code>step &gt; 1</code> → <code>decrementStep()</code>; <code>step === 1</code> → <code>closePopupAuth()</code>.<br> ✕ (только mobile) → <code>settingsStore.closeApp()</code> (весь виджет).</p><hr><h2 id="authenticationview" tabindex="-1">AuthenticationView <a class="header-anchor" href="#authenticationview" aria-label="Permalink to &quot;AuthenticationView&quot;">​</a></h2><p><strong>Путь:</strong> <code>views/AuthenticationView/AuthenticationView.vue</code></p><p>Оболочка: фон, back, close, logo, title, form / errors.</p><h3 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Поведение</th></tr></thead><tbody><tr><td><code>backHandler</code></td><td>decrement / close popup</td></tr><tr><td><code>closeWidget</code></td><td><code>settingsStore.closeApp()</code></td></tr><tr><td><code>showError(code)</code></td><td>fullscreen <code>AuthenticationErrors</code></td></tr></tbody></table><h3 id="watch-geterror-→-fullscreen" tabindex="-1">Watch <code>getError</code> → fullscreen <a class="header-anchor" href="#watch-geterror-→-fullscreen" aria-label="Permalink to &quot;Watch \`getError\` → fullscreen&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>error</code></th><th><code>codeError</code></th><th>Экран</th></tr></thead><tbody><tr><td><code>sms_rate_limited</code></td><td>1</td><td>Лимит запросов SMS</td></tr><tr><td><code>too_many_attempts</code></td><td>2</td><td>Исчерпаны попытки кода</td></tr><tr><td><code>session_sms_limit</code></td><td>3</td><td>Лимит номеров сессии</td></tr><tr><td><code>expired</code></td><td>4</td><td>Код истёк</td></tr><tr><td><code>null</code></td><td>—</td><td>Вернуть форму</td></tr></tbody></table><p>При <code>isShowError</code>: title + form скрыты (<code>v-show</code>).</p><h3 id="mobile-ux" tabindex="-1">Mobile UX <a class="header-anchor" href="#mobile-ux" aria-label="Permalink to &quot;Mobile UX&quot;">​</a></h3><p>Fixed overlay на <code>laptop-lower</code>; close-кнопка только mobile (на laptop <code>display: none</code>).</p><h3 id="кто-открывает-popup" tabindex="-1">Кто открывает popup <a class="header-anchor" href="#кто-открывает-popup" aria-label="Permalink to &quot;Кто открывает popup&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Место</th><th>Вызов</th></tr></thead><tbody><tr><td><code>SidebarLogin</code> / <code>SidebarPopover</code> / <code>ChatNotify</code></td><td><code>openPopupAuth()</code></td></tr><tr><td><code>NewChat</code> (гость + лимит)</td><td><code>openPopupAuth(true)</code> → <code>isOpenFromChat</code></td></tr><tr><td><code>useAuthPhone</code> (popup ещё закрыт)</td><td><code>openPopupAuth()</code></td></tr></tbody></table><hr><h2 id="authenticationform" tabindex="-1">AuthenticationForm <a class="header-anchor" href="#authenticationform" aria-label="Permalink to &quot;AuthenticationForm&quot;">​</a></h2><p>Роутер: <code>step === 1|2|3</code> → Phone / Code / Name (<code>v-if</code>, unmount при смене).</p><hr><h2 id="authenticationformphone-шаг-1" tabindex="-1">AuthenticationFormPhone (шаг 1) <a class="header-anchor" href="#authenticationformphone-шаг-1" aria-label="Permalink to &quot;AuthenticationFormPhone (шаг 1)&quot;">​</a></h2><p>Вся логика через <code>useAuthPhone</code>.</p><p>UI: <code>ErrorInput</code> + маска <code>+7 (###) ###-##-##</code> + «Продолжить» + <code>AgreementComponent</code>.</p><p>Коды <code>sms_rate_limited</code> / <code>session_sms_limit</code> дублируются: inline <code>authError</code> и fullscreen View.</p><hr><h2 id="authenticationformcode-шаг-2" tabindex="-1">AuthenticationFormCode (шаг 2) <a class="header-anchor" href="#authenticationformcode-шаг-2" aria-label="Permalink to &quot;AuthenticationFormCode (шаг 2)&quot;">​</a></h2><h3 id="state-computed" tabindex="-1">State / computed <a class="header-anchor" href="#state-computed" aria-label="Permalink to &quot;State / computed&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>code</code></td><td>OTP, v-model <code>SmsCodeInput</code></td></tr><tr><td><code>disabledButton</code></td><td>длина ≠ 6 или <code>isSend</code></td></tr><tr><td><code>durationDisable</code></td><td>из store → <code>TimerComponent</code></td></tr><tr><td><code>userName</code></td><td>ветка close vs step 3</td></tr></tbody></table><h3 id="buttonclickhandler" tabindex="-1"><code>buttonClickHandler</code> <a class="header-anchor" href="#buttonclickhandler" aria-label="Permalink to &quot;\`buttonClickHandler\`&quot;">​</a></h3><ol><li><code>verifyCode(code)</code></li><li><code>upgradeSession()</code> → cookies + возможно <code>userName</code></li><li><code>chatStore.fetchUserChats()</code></li><li><code>userName</code> ? <code>closePopupAuth()</code> : <code>incrementStep()</code></li></ol><h3 id="повторная-отправка" tabindex="-1">Повторная отправка <a class="header-anchor" href="#повторная-отправка" aria-label="Permalink to &quot;Повторная отправка&quot;">​</a></h3><ul><li>Таймер <code>durationDisable</code> сек → <code>@finish</code> включает «Отправить код повторно».</li><li><code>repeatSendConde</code> → <code>sendCode()</code> → снова таймер.</li><li>Смена <code>code</code> сбрасывает store error; <code>error → null</code> → <code>timer.restart()</code>.</li></ul><h3 id="inline-ошибки-otp" tabindex="-1">Inline-ошибки OTP <a class="header-anchor" href="#inline-ошибки-otp" aria-label="Permalink to &quot;Inline-ошибки OTP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Код</th><th>Текст</th></tr></thead><tbody><tr><td><code>wrong_code</code></td><td>«Неверный код»</td></tr><tr><td><code>not_found</code></td><td>«Время жизни кода вышло»</td></tr><tr><td><code>validation_failed</code></td><td>«Неверный формат…»</td></tr><tr><td><code>rate_limited</code></td><td>«Слишком частые попытки…»</td></tr></tbody></table><hr><h2 id="authenticationformname-шаг-3" tabindex="-1">AuthenticationFormName (шаг 3) <a class="header-anchor" href="#authenticationformname-шаг-3" aria-label="Permalink to &quot;AuthenticationFormName (шаг 3)&quot;">​</a></h2><p>Только если после upgrade имя ещё не задано.</p><table tabindex="0"><thead><tr><th>Правило</th><th>Значение</th></tr></thead><tbody><tr><td>Длина</td><td>3…20</td></tr><tr><td>Алфавит</td><td>только кириллица, слова через один пробел (<code>/^[а-яА-ЯёЁ]+(\\s[а-яА-ЯёЁ]+)*$/</code>)</td></tr><tr><td>Согласие</td><td>обязательно</td></tr></tbody></table><p>Успех → <code>changeUserName</code> → <code>closePopupAuth()</code>. Клиентские ошибки через <code>setErrorInfo</code> + автоочистка ~2 с.</p><hr><h2 id="authenticationtitle-logo-errors" tabindex="-1">AuthenticationTitle / Logo / Errors <a class="header-anchor" href="#authenticationtitle-logo-errors" aria-label="Permalink to &quot;AuthenticationTitle / Logo / Errors&quot;">​</a></h2><h3 id="title" tabindex="-1">Title <a class="header-anchor" href="#title" aria-label="Permalink to &quot;Title&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Заголовок</th><th>Подзаголовок</th></tr></thead><tbody><tr><td>1 + <code>isOpenFromChat</code></td><td>«Войдите или создайте аккаунт»</td><td>про создание нового чата</td></tr><tr><td>1 иначе</td><td>то же</td><td>про сохранение чатов</td></tr><tr><td>2</td><td>«Проверьте SMS»</td><td>номер <code>formattedPhone</code></td></tr><tr><td>3</td><td>«Давайте познакомимся!»</td><td>как вас зовут</td></tr></tbody></table><h3 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h3><p>Статичный <code>LogoFull</code>, без props/store.</p><h3 id="errors-codeerror" tabindex="-1">Errors (<code>codeError</code>) <a class="header-anchor" href="#errors-codeerror" aria-label="Permalink to &quot;Errors (\`codeError\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>CTA</th></tr></thead><tbody><tr><td>1 / 3</td><td>«Продолжить» → <code>clearError</code> (<code>setErrorInfo(null)</code> + <code>setStep(1)</code>)</td></tr><tr><td>2</td><td>«Изменить номер» → clear; «Отправить повторно» → <code>sendCode</code> + <code>setStep(2)</code></td></tr><tr><td>4</td><td>«Отправить код повторно» → <code>sendCode</code> + step 2</td></tr></tbody></table><hr><h2 id="связи-с-чатом-и-саидбаром" tabindex="-1">Связи с чатом и сайдбаром <a class="header-anchor" href="#связи-с-чатом-и-саидбаром" aria-label="Permalink to &quot;Связи с чатом и сайдбаром&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Сценарий</th><th>Связь</th></tr></thead><tbody><tr><td>Баннер «войдите» / unauthorized popover / NewChat</td><td><code>openPopupAuth</code></td></tr><tr><td>После успешного кода</td><td><code>fetchUserChats()</code></td></tr><tr><td>Axios 401 на <code>/chats</code></td><td><code>updateToken</code> → retry; fail → <code>logout</code> + <code>clearAllChats</code></td></tr><tr><td>Logout / delete account</td><td><code>clearAllChats</code> + <code>chat:clear-visual</code></td></tr><tr><td>SidebarLogin</td><td>тот же <code>useAuthPhone</code></td></tr></tbody></table><p>См. также: <a href="./chat">Chat</a> (interceptor, ChatNotify), <a href="./sidebar">Sidebar</a> (Login, User popover).</p><hr><h2 id="сводка-props-emits" tabindex="-1">Сводка props / emits <a class="header-anchor" href="#сводка-props-emits" aria-label="Permalink to &quot;Сводка props / emits&quot;">​</a></h2><p>Почти все Vue-компоненты auth <strong>без props/emits</strong> — коммуникация через Pinia.<br> Исключение: <code>AuthenticationErrors</code> — prop <code>codeError?: number</code> (default <code>1</code>).</p>`,97)])])}const b=e(r,[["render",c]]);export{u as __pageData,b as default};
